#!/usr/bin/env node

/**
 * Checkpoint Command - Comprehensive development checkpoint
 * 
 * This command:
 * 1. Analyzes all git changes
 * 2. Updates documentation based on changes
 * 3. Commits everything with proper message
 * 4. Pushes to remote branch
 */

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

function runCommand(cmd, options = {}) {
  try {
    const result = execSync(cmd, { 
      encoding: 'utf8', 
      stdio: options.silent ? 'pipe' : 'inherit',
      ...options 
    });
    return result.trim();
  } catch (error) {
    if (!options.allowFailure) {
      console.error(`❌ Command failed: ${cmd}`);
      console.error(error.message);
      process.exit(1);
    }
    return null;
  }
}

function getCurrentBranch() {
  return runCommand('git branch --show-current', { silent: true });
}

function getRemoteTrackingBranch() {
  try {
    return runCommand('git rev-parse --abbrev-ref @{upstream}', { silent: true, allowFailure: true });
  } catch {
    return null;
  }
}

function analyzeGitChanges() {
  const status = runCommand('git status --porcelain', { silent: true });
  const staged = runCommand('git diff --cached --name-only', { silent: true });
  const modified = runCommand('git diff --name-only', { silent: true });
  const untracked = runCommand('git ls-files --others --exclude-standard', { silent: true });

  return {
    hasChanges: status.length > 0,
    staged: staged ? staged.split('\n').filter(Boolean) : [],
    modified: modified ? modified.split('\n').filter(Boolean) : [],
    untracked: untracked ? untracked.split('\n').filter(Boolean) : [],
    allFiles: status ? status.split('\n').filter(Boolean).map(line => line.substring(3)) : []
  };
}

function analyzeChangeTypes(changes) {
  const categories = {
    features: [],
    fixes: [],
    components: [],
    utils: [],
    types: [],
    tests: [],
    migrations: [],
    docs: [],
    config: []
  };

  const patterns = {
    features: /\/(pages|features)\//,
    components: /\/components\//,
    utils: /\/utils\//,
    types: /\/types\//,
    tests: /\.(test|spec)\./,
    migrations: /\/migrations\//,
    fixes: /fix|bug|error/i,
    docs: /\.(md|txt)$/,
    config: /\.(json|js|ts)config|package\.json|\.env/
  };

  changes.allFiles.forEach(file => {
    let categorized = false;

    Object.entries(patterns).forEach(([category, pattern]) => {
      if (pattern.test(file) && !categorized) {
        categories[category].push(file);
        categorized = true;
      }
    });

    if (!categorized) {
      categories.features.push(file); // Default to features
    }
  });

  return categories;
}

function generateCommitMessage(changes, categories, customMessage) {
  if (customMessage) {
    return `${customMessage}

🤖 Generated with [Claude Code](https://claude.ai/code)

Co-Authored-By: Claude <noreply@anthropic.com>`;
  }

  let message = '';
  let type = 'feat';

  // Determine primary change type
  if (categories.fixes.length > 0) {
    type = 'fix';
    message = 'fix: ';
  } else if (categories.migrations.length > 0) {
    type = 'feat';
    message = 'feat: ';
  } else if (categories.components.length > 0) {
    type = 'feat';
    message = 'feat: ';
  } else {
    type = 'feat';
    message = 'feat: ';
  }

  // Generate description based on changes
  const descriptions = [];

  if (categories.migrations.length > 0) {
    descriptions.push(`add database migrations (${categories.migrations.length} files)`);
  }

  if (categories.components.length > 0) {
    descriptions.push(`update components (${categories.components.length} files)`);
  }

  if (categories.utils.length > 0) {
    descriptions.push(`enhance utilities (${categories.utils.length} files)`);
  }

  if (categories.fixes.length > 0) {
    descriptions.push(`resolve issues (${categories.fixes.length} files)`);
  }

  if (descriptions.length === 0) {
    descriptions.push(`update ${changes.allFiles.length} files`);
  }

  message += descriptions.join(', ');

  return `${message}

🤖 Generated with [Claude Code](https://claude.ai/code)

Co-Authored-By: Claude <noreply@anthropic.com>`;
}

function updateClaudeMd(categories) {
  const claudeMdPath = path.join(process.cwd(), 'CLAUDE.md');

  if (!fs.existsSync(claudeMdPath)) {
    console.log('⚠️  CLAUDE.md not found, skipping documentation update');
    return;
  }

  let content = fs.readFileSync(claudeMdPath, 'utf8');
  let updated = false;

  // Add new component patterns if components were modified
  if (categories.components.length > 0) {
    const componentNote = `
### Recent Component Updates
- Updated components: ${categories.components.slice(0, 3).join(', ')}${categories.components.length > 3 ? ` and ${categories.components.length - 3} more` : ''}
- Last updated: ${new Date().toISOString().split('T')[0]}
`;

    if (!content.includes('### Recent Component Updates')) {
      // Add after Architecture Overview
      content = content.replace(
        '### Project Structure',
        componentNote + '\n### Project Structure'
      );
      updated = true;
    }
  }

  // Add migration notes if present
  if (categories.migrations.length > 0) {
    const migrationNote = `
### Recent Database Changes
- New migrations: ${categories.migrations.join(', ')}
- Run these in Supabase SQL editor
- Last updated: ${new Date().toISOString().split('T')[0]}
`;

    if (!content.includes('### Recent Database Changes')) {
      content = content.replace(
        '### Database Schema',
        migrationNote + '\n### Database Schema'
      );
      updated = true;
    }
  }

  if (updated) {
    fs.writeFileSync(claudeMdPath, content);
    console.log('📝 Updated CLAUDE.md with recent changes');
  }
}

function main() {
  const args = process.argv.slice(2);
  const customMessage = args.join(' ').trim() || null;

  console.log('🔍 Analyzing repository changes...\n');

  // Validate git repository
  const currentBranch = getCurrentBranch();
  if (!currentBranch) {
    console.error('❌ Not in a git repository');
    process.exit(1);
  }

  console.log(`📍 Current branch: ${currentBranch}`);

  // Safety check - don't commit directly to main
  if (currentBranch === 'main' || currentBranch === 'master') {
    console.error('❌ Cannot checkpoint on main/master branch. Please switch to a feature branch.');
    process.exit(1);
  }

  // Analyze changes
  const changes = analyzeGitChanges();

  if (!changes.hasChanges) {
    console.log('✅ No changes detected. Repository is clean.');
    return;
  }

  console.log(`📊 Found changes in ${changes.allFiles.length} files:`);
  console.log(`   • Staged: ${changes.staged.length}`);
  console.log(`   • Modified: ${changes.modified.length}`);
  console.log(`   • Untracked: ${changes.untracked.length}\n`);

  // Categorize changes
  const categories = analyzeChangeTypes(changes);

  Object.entries(categories).forEach(([category, files]) => {
    if (files.length > 0) {
      console.log(`📁 ${category}: ${files.length} files`);
      files.slice(0, 3).forEach(file => console.log(`   - ${file}`));
      if (files.length > 3) {
        console.log(`   ... and ${files.length - 3} more`);
      }
    }
  });

  console.log('\n🔄 Updating documentation...');

  // Update documentation
  updateClaudeMd(categories);

  console.log('\n📦 Staging all changes...');

  // Stage all changes
  runCommand('git add .');

  // Generate commit message
  const commitMessage = generateCommitMessage(changes, categories, customMessage);

  console.log('\n📝 Commit message:');
  console.log('---');
  console.log(commitMessage);
  console.log('---\n');

  // Commit changes
  console.log('💾 Creating commit...');
  runCommand(`git commit -m "${commitMessage.replace(/"/g, '\\"')}"`);

  // Check for remote tracking
  const remoteBranch = getRemoteTrackingBranch();

  if (remoteBranch) {
    console.log(`🚀 Pushing to ${remoteBranch}...`);
    runCommand(`git push origin ${currentBranch}`);
    console.log('✅ Successfully pushed to remote!');
  } else {
    console.log('📡 Setting up remote tracking and pushing...');
    try {
      runCommand(`git push -u origin ${currentBranch}`);
      console.log('✅ Successfully pushed to remote with tracking!');
    } catch (error) {
      console.log('⚠️  Could not push to remote. You may need to push manually.');
    }
  }

  console.log('\n🎉 Checkpoint complete!');
  console.log(`✨ Changes committed to branch: ${currentBranch}`);
}

if (require.main === module) {
  main();
}

module.exports = { main };
